<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --defaults-extra-file=/root/.my-backup.cnf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
